import{_ as t,o as e,a as i,b as s}from"./app.DKoEZOcr.js";const c="/ascendc.github.io/pr/5487/assets/batch_bias.ClMxTZct.png",r="/ascendc.github.io/pr/5487/assets/bias_reuse.e9kYOvWM.png",u=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"SIMD算子实现","link":"/guide/operator_practice/simd_operator_impl/simd_operator_impl"},{"text":"矩阵编程（高阶API）","link":"/guide/operator_practice/simd_operator_impl/matrix_advanced_api/matrix_advanced_api"},{"text":"特性场景","link":"/guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/matmul_features"},{"text":"Batch Matmul复用Bias矩阵","link":"/guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/batch_matmul_reuse_bias"}]},"headers":[],"relativePath":"guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/batch_matmul_reuse_bias.md","filePath":"guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/batch_matmul_reuse_bias.md","outlineHeaders":[{"level":2,"title":"功能介绍","slug":"功能介绍","link":"#功能介绍"},{"level":2,"title":"使用场景","slug":"使用场景","link":"#使用场景"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1786954352000}'),_={name:"guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/batch_matmul_reuse_bias.md"};function n(o,a,p,l,m,d){return e(),i("div",null,[...a[0]||(a[0]=[s('<div><article class="markdown-body"><h1>Batch Matmul复用Bias矩阵<span id="ZH-CN_TOPIC_0000002500548102"></span></h1><h2 id="功能介绍">功能介绍<span id="zh-cn_topic_0000002373911153_section1953745712231"></span><a class="header-anchor" href="#功能介绍">​</a></h2><p>在Batch Matmul场景中，Matmul API可以一次性计算出多个大小为singleCoreM * singleCoreN的C矩阵。当Batch Matmul场景有Bias输入时，默认的Bias输入矩阵包含Batch轴，即Bias的大小为Batch * N。通过开启Bias复用功能，当每个Batch计算使用的Bias数据相同时，只需输入一个不带Batch轴的Bias矩阵。Batch Matmul的Bias矩阵复用功能默认不启用，用户需要设置<a href="../../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/MatmulConfig.html">MatmulConfig</a>中的isBiasBatch参数为false来开启此功能。</p><p><strong>图1</strong> 带有Batch轴的Bias计算示意图<span id="zh-cn_topic_0000002373911153_fig889710263325"></span><br><img src="'+c+'" alt title="带有Batch轴的Bias计算示意图"></p><p>如上图所示，Batch Matmul中未复用Bias矩阵的场景，每计算出一个singleCoreM * singleCoreN大小的C矩阵，都会与1 * singleCoreN大小的Bias矩阵相加。若不同Batch的计算使用的Bias数据相同，则多Batch计算可以复用同一个Bias矩阵，如下图所示，此场景中调用<a href="../../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/SetBias.html">SetBias</a>接口时，只需设置一个1 * singleCoreN大小的Bias矩阵。</p><p><strong>图2</strong> 复用Bias计算示意图<span id="zh-cn_topic_0000002373911153_fig1485726153719"></span><br><img src="'+r+`" alt title="复用Bias计算示意图"></p><h2 id="使用场景">使用场景<span id="zh-cn_topic_0000002373911153_section1672510573541"></span><a class="header-anchor" href="#使用场景">​</a></h2><p>Batch Matmul中每个Batch的Matmul计算可以使用相同的Bias矩阵。</p><h2 id="约束说明">约束说明<span id="zh-cn_topic_0000002373911153_section3618165412115"></span><a class="header-anchor" href="#约束说明">​</a></h2><p>A、B、C矩阵的Layout类型都为NORMAL时，不支持<a href="../../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/MatmulConfig.html">batchMode</a>参数设为SINGLE_LARGE_THAN_L1，即Bias复用场景下，单Batch的A、B矩阵数据总和不得超过L1 Buffer的大小。</p><h2 id="调用示例">调用示例<span id="zh-cn_topic_0000002373911153_section18018102212"></span><a class="header-anchor" href="#调用示例">​</a></h2><p>完整的算子样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/04_advanced_api/00_matmul/batch_matmul_bias_reuse">BatchMatmul复用Bias算子样例</a>。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>// 自定义MatmulConfig参数，将其中的isBiasBatch参数设置为false，开启BatchMatmul的Bias复用功能。
constexpr MatmulConfigMode configMode = MatmulConfigMode::CONFIG_NORM;
constexpr MatmulBatchParams batchParams = {
  false, BatchMode::BATCH_LESS_THAN_L1, false /* isBiasBatch */
};
constexpr MatmulConfig CFG_MM = GetMMConfig&lt;configMode&gt;(batchParams);
AscendC::Matmul&lt;A_TYPE, B_TYPE, C_TYPE, BIAS_TYPE, CFG_MM&gt; mm;

REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm, &amp;tiling); // 初始化matmul对象
mm.SetTensorA(gm_a);    // 设置左矩阵A
mm.SetTensorB(gm_b);    // 设置右矩阵B
mm.SetBias(gm_bias);    // 设置Bias，矩阵大小为1 * singleCoreN
mm.IterateBatch(gm_c, batchA, batchB, false);
mm.End();
</code></pre></div></article></div>`,1)])])}const B=t(_,[["render",n]]);export{u as __pageData,B as default};
